n = int(input())
# 外层遍历,遍历行数
for i in range(1, 2 * n):
    # 内层遍历,遍历列数
    for j in range(1, 2 * n):
        # 是否处于菱形的左上角那条边
        if i + j == n + 1:
            print('+', end='')
        # 是否处于菱形的右下角那条边
        elif i + j == 3 * n - 1:
            print('+', end='')
        # 是否处于菱形的左下角或者右上角那条边
        elif i - j == n - 1 or j - i == n - 1:
            print('+', end='')
        # 其它的位置都是'.'
        else:
            print('.', end='')
    print()
